import React from 'react';
import './SharedWithMePage.css';

const mockShared = [
  {
    shareId: 1,
    sender: { username: 'johndoe', displayName: 'John Doe' },
    playlist: { playlistId: 2, title: 'Chill Vibes', songCount: 16 },
    message: 'Thought you might like this one!',
    sharedAt: 'March 27, 2026',
  },
  {
    shareId: 2,
    sender: { username: 'alicesmith', displayName: 'Alice Smith' },
    playlist: { playlistId: 3, title: 'Late Night Study', songCount: 18 },
    message: '',
    sharedAt: 'March 25, 2026',
  },
  {
    shareId: 3,
    sender: { username: 'mikejones', displayName: 'Mike Jones' },
    playlist: { playlistId: 4, title: 'Workout Bangers', songCount: 20 },
    message: 'Perfect for the gym!',
    sharedAt: 'March 22, 2026',
  },
];

function getInitials(displayName) {
  return displayName.split(' ').map(w => w[0]).join('').toUpperCase();
}

function SharedWithMePage() {
  return (
    <div className="shared-container">
      <h1 className="shared-title">Shared With Me</h1>
      <p className="shared-subtitle">Playlists your friends have sent you</p>

      {mockShared.length === 0 ? (
        <div className="shared-empty">
          <p>No playlists shared with you yet.</p>
        </div>
      ) : (
        <div className="shared-list">
          {mockShared.map(item => (
            <div key={item.shareId} className="shared-card">
              <div className="shared-sender">
                <div className="sender-avatar">{getInitials(item.sender.displayName)}</div>
                <div className="sender-info">
                  <span className="sender-name">{item.sender.displayName}</span>
                  <span className="sender-date">shared on {item.sharedAt}</span>
                </div>
              </div>

              <div className="shared-playlist-info">
                <h3 className="shared-playlist-title">{item.playlist.title}</h3>
                <p className="shared-playlist-meta">{item.playlist.songCount} songs</p>
                {item.message !== '' && (
                  <div className="shared-message">"{item.message}"</div>
                )}
              </div>

              
                href={`/playlist/${item.playlist.playlistId}`}
                className="shared-view-btn"
              <a>
                View Playlist →
              </a>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default SharedWithMePage;
